1	package system
2	
3	import (
4		"bytes"
5		"fmt"
6		"os"
7		"path/filepath"
8		"text/template"
9	
10		intropytemplate "github.com/integrio-intropy/intropy-cli/internal/template"
11	)
12	
13	// The generated declaration files. Deliberately namespace-less: the host
14	// project is small enough that the declaration reads as one document, and
15	// discovery reflects over the assembly regardless.
16	const topicsFileTmpl = `using Intropy.Topology;
17	using {{ .Shared.Name }};
18	
19	/// <summary>The system's topics, each defined once and shared by every component that touches it.</summary>
20	public static class Topics
21	{
22	{{- range $i, $t := .Topics }}
23	{{- if $i }}
24	{{ end }}
25	    /// <summary>{{ $t.Contract }} messages on topic '{{ $t.Name }}' (pubsub '{{ $t.Pubsub }}').</summary>
26	    public static readonly TopicRef<{{ $t.Contract }}> {{ $t.Field }} = TopicRef<{{ $t.Contract }}>.Define("{{ $t.Pubsub }}", "{{ $t.Name }}");
27	{{- end }}
28	}
29	`
30	
31	const systemClassFileTmpl = `using Intropy.Topology;
32	
33	/// <summary>The {{ .Name }} system: what exists, and what connects it.</summary>
34	public sealed class {{ .SystemClass }} : ISystemDefinition
35	{
36	    public string SystemName => "{{ .Name }}";
37	
38	    public void Define(SystemBuilder builder)
39	    {
40	{{- range .Components }}
41	        builder.{{ .Add }}("{{ .AppID }}").{{ .Edge }}(Topics.{{ .Field }});
42	{{- end }}
43	    }
44	}
45	`
46	
47	var (
48		topicsFile      = template.Must(template.New("Topics.cs").Parse(topicsFileTmpl))
49		systemClassFile = template.Must(template.New("SystemClass.cs").Parse(systemClassFileTmpl))
50	)
51	
52	// componentView is a Component with its builder call and topic field
53	// resolved for the system class template.
54	type componentView struct {
55		AppID string
56		Add   string // AddExtractor | AddLoader
57		Edge  string // Publishes | Subscribes
58		Field string // the Topics.cs field the component touches
59	}
60	
61	// writeTopicsFile overwrites <dir>/Topics.cs with the assembled topic
62	// declarations.
63	func writeTopicsFile(dir string, m *Model) error {
64		return renderTo(filepath.Join(dir, "Topics.cs"), topicsFile, m)
65	}
66	
67	// writeSystemClassFile overwrites <dir>/<SystemClass>.cs with the assembled
68	// system definition. It refuses to create the file: the rendered template
69	// must have left the placeholder, or its name derivation disagrees with
70	// this CLI and the write would add a second ISystemDefinition instead of
71	// replacing the placeholder.
72	func writeSystemClassFile(dir string, m *Model) error {
73		path := filepath.Join(dir, m.SystemClass+".cs")
74		if _, err := os.Stat(path); err != nil {
75			return fmt.Errorf("template rendered no %s.cs placeholder: the template's systemClass derivation disagrees with this CLI; upgrade intropy or pass --version <compatible tag>", m.SystemClass)
76		}
77	
78		views := make([]componentView, len(m.Components))
79		fieldByKey := map[TopicKey]string{}
80		for _, t := range m.Topics {
81			fieldByKey[t.TopicKey] = t.Field
82		}
83		for i, c := range m.Components {
84			v := componentView{AppID: c.AppID, Field: fieldByKey[c.Topic]}
85			if c.Kind == intropytemplate.BlockKindExtractor {
86				v.Add, v.Edge = "AddExtractor", "Publishes"
87			} else {
88				v.Add, v.Edge = "AddLoader", "Subscribes"
89			}
90			views[i] = v
91		}
92	
93		return renderTo(path, systemClassFile, struct {
94			Name        string
95			SystemClass string
96			Components  []componentView
97		}{m.Name, m.SystemClass, views})
98	}
99	
100	func renderTo(path string, tmpl *template.Template, data any) error {
101		var buf bytes.Buffer
102		if err := tmpl.Execute(&buf, data); err != nil {
103			return fmt.Errorf("generate %s: %w", filepath.Base(path), err)
104		}
105		if err := os.WriteFile(path, buf.Bytes(), 0o644); err != nil {
106			return fmt.Errorf("generate %s: %w", filepath.Base(path), err)
107		}
108		return nil
109	}
