/// Every edge block reaches the outside world through a connector. Its transport selects
/// the Dapr binding type it materializes as; the Dapr binding component's name is always
/// derived (<c>binding.&lt;connector-name&gt;</c>), never declared. Connectors are declared
/// in the SystemHost (typically a scaffolded <c>Connectors.cs</c>); they are system-owned and
/// never shared across systems. Direction is not part of the identity — it follows from
/// usage (<c>From</c> / <c>To</c> / <c>Trigger.Connector</c>).
/// <para>
/// Only the connector's <em>name</em> is intrinsic to a component — it is the local port the
/// component reads from or writes to. Both <em>what</em> it connects to (the external system)
/// and <em>how</em> (the transport) are resolution concerns, bound together at a later
/// system-assembly step (<c>intropy system create</c>), not at block scaffolding
/// (<c>intropy int create</c>). A connector declared by name only is <em>unresolved</em>; so is
/// one still missing its external system or transport. An unresolved connector still builds and
/// validates — it surfaces as a warning (ITP107) rather than an error, and its direction
/// capabilities go unchecked until a transport is set.
/// </para>
/// </summary>
public sealed record ConnectorRef
{
    /// <summary>The connector's name (DNS-1123 label, e.g. <c>pim</c>).</summary>
    public string Name { get; }

    /// <summary>
    /// The external system the connector connects to, or <see langword="null"/> when the connector
    /// is unresolved (its external system is deferred to system assembly).
    /// </summary>
    public ExternalSystem? System { get; }

    /// <summary>
    /// The transport — the kind of Dapr binding the connector materializes as, or <see langword="null"/>
    /// when the connector is unresolved (its transport is deferred to system assembly).
    /// </summary>
    public Transport? Transport { get; }

    private ConnectorRef(string name, ExternalSystem? system, Transport? transport)
    {
        Name = name;
        System = system;
        Transport = transport;
    }

    /// <summary>Declares a fully resolved connector — external system and transport both known.</summary>
    /// <param name="name">The connector's name (DNS-1123 label).</param>
    /// <param name="system">The external system the connector connects to.</param>
    /// <param name="transport">The kind of Dapr binding the connector materializes as.</param>
    /// <exception cref="ArgumentException">The name is not a valid DNS-1123 label.</exception>
    public static ConnectorRef Define(
        [ConstantExpected] string name, ExternalSystem system, Transport transport)
    {
        ArgumentNullException.ThrowIfNull(system);
        ArgumentNullException.ThrowIfNull(transport);
        return new ConnectorRef(NameRules.RequireLabel(name, nameof(name)), system, transport);
    }

    /// <summary>
    /// Declares a partially resolved connector — its external system is known but its transport is
    /// deferred to system assembly. The connector builds and validates; the missing transport is
    /// reported as a warning (ITP107), and direction capabilities go unchecked until it is resolved.
    /// </summary>
    /// <param name="name">The connector's name (DNS-1123 label).</param>
    /// <param name="system">The external system the connector connects to.</param>
    /// <exception cref="ArgumentException">The name is not a valid DNS-1123 label.</exception>
    public static ConnectorRef Define([ConstantExpected] string name, ExternalSystem system)
    {
        ArgumentNullException.ThrowIfNull(system);
        return new ConnectorRef(NameRules.RequireLabel(name, nameof(name)), system, transport: null);
    }

    /// <summary>
    /// Declares an <em>unresolved</em> connector by name only — the form a block scaffold
    /// (<c>intropy int create</c>) emits. Both the external system it connects to and its transport
    /// are deferred to system assembly (<c>intropy system create</c>). The connector builds and
    /// validates; its unresolved state is reported as a warning (ITP107), and direction capabilities
    /// go unchecked until a transport is set.
    /// </summary>
    /// <param name="name">The connector's name (DNS-1123 label).</param>
    /// <exception cref="ArgumentException">The name is not a valid DNS-1123 label.</exception>
    public static ConnectorRef Define([ConstantExpected] string name) =>
        new(NameRules.RequireLabel(name, nameof(name)), system: null, transport: null);
}

/// <summary>
/// Names an external system (e.g. a PIM or ERP) that the integration system talks to
/// through bindings. Pure identity with value equality.
/// </summary>
public sealed record ExternalSystem
{
    /// <summary>The external system's name (DNS-1123 label, e.g. <c>pim</c>).</summary>
    public string Name { get; }

    /// <summary>Creates an external system identity.</summary>
    /// <param name="name">The external system's name (DNS-1123 label).</param>
    /// <exception cref="ArgumentException">The name is not a valid DNS-1123 label.</exception>
    public ExternalSystem(string name)
    {
        Name = NameRules.RequireLabel(name, nameof(name));
    }
}

/// <summary>
/// The kind of Dapr binding a connector materializes as. All connectivity goes through

/// The kind of Dapr binding a connector materializes as. All connectivity goes through
/// Dapr (HTTP and SFTP included) — the transport selects the Dapr binding component's
/// <c>spec.type</c>; it never bypasses Dapr. The component name is always derived:
/// <c>binding.&lt;connector-name&gt;</c>.
/// </summary>
[JsonPolymorphic(TypeDiscriminatorPropertyName = "$transport")]
[JsonDerivedType(typeof(HttpTransport), "http")]
[JsonDerivedType(typeof(SftpTransport), "sftp")]
[JsonDerivedType(typeof(BlobTransport), "blob")]
[JsonDerivedType(typeof(CustomTransport), "custom")]
public abstract record Transport
{
    private protected Transport()
    {
    }

    /// <summary>The Dapr binding component's <c>spec.type</c> (e.g. <c>bindings.http</c>).</summary>
    public abstract string DaprType { get; }

    /// <summary>Whether the Dapr binding type supports input usage (<c>From</c> / <c>Trigger.Connector</c>).</summary>
    public abstract bool SupportsInput { get; }

    /// <summary>Whether the Dapr binding type supports output usage (<c>To</c>).</summary>
    public abstract bool SupportsOutput { get; }

    /// <summary>HTTP transport (<c>bindings.http</c>) — output-only in Dapr.</summary>
    public static Transport Http() => new HttpTransport();

    /// <summary>SFTP transport (<c>bindings.sftp</c>).</summary>
    public static Transport Sftp() => new SftpTransport();

    /// <summary>Azure Blob Storage transport (<c>bindings.azure.blobstorage</c>).</summary>
    public static Transport Blob() => new BlobTransport();

    /// <summary>Escape hatch for any other Dapr binding type.</summary>
    /// <param name="daprType">The Dapr binding component's <c>spec.type</c> (e.g. <c>bindings.kafka</c>).</param>
    /// <param name="supportsInput">Whether the Dapr binding type supports input usage.</param>
    /// <param name="supportsOutput">Whether the Dapr binding type supports output usage.</param>
    /// <exception cref="ArgumentException">The Dapr binding type is null or whitespace.</exception>
    public static Transport Custom(
        [ConstantExpected] string daprType, bool supportsInput = true, bool supportsOutput = true)
        => new CustomTransport(daprType, supportsInput, supportsOutput);
}

/// <summary>HTTP transport: a Dapr binding component of type <c>bindings.http</c> (output-only in Dapr).</summary>
public sealed record HttpTransport : Transport
{
    /// <inheritdoc />
    public override string DaprType => "bindings.http";

    /// <inheritdoc />
    public override bool SupportsInput => false;

    /// <inheritdoc />
    public override bool SupportsOutput => true;
}

/// <summary>SFTP transport: a Dapr binding component of type <c>bindings.sftp</c>.</summary>
public sealed record SftpTransport : Transport
{
    /// <inheritdoc />
    public override string DaprType => "bindings.sftp";

    /// <inheritdoc />
    public override bool SupportsInput => true;

    /// <inheritdoc />
    public override bool SupportsOutput => true;
}

/// <summary>Azure Blob Storage transport: a Dapr binding component of type <c>bindings.azure.blobstorage</c>.</summary>
public sealed record BlobTransport : Transport
{
    /// <inheritdoc />
    public override string DaprType => "bindings.azure.blobstorage";

    /// <inheritdoc />
    public override bool SupportsInput => true;

    /// <inheritdoc />
    public override bool SupportsOutput => true;
}

/// <summary>A custom transport: any other Dapr binding type, declared via <see cref="Transport.Custom"/>.</summary>
public sealed record CustomTransport : Transport
{
    /// <inheritdoc />
    public override string DaprType { get; }

    /// <inheritdoc />
    public override bool SupportsInput { get; }

    /// <inheritdoc />
    public override bool SupportsOutput { get; }

    /// <summary>Creates a custom transport. Prefer <see cref="Transport.Custom"/>.</summary>
    /// <param name="daprType">The Dapr binding component's <c>spec.type</c>.</param>
    /// <param name="supportsInput">Whether the Dapr binding type supports input usage.</param>
    /// <param name="supportsOutput">Whether the Dapr binding type supports output usage.</param>
    /// <exception cref="ArgumentException">The Dapr binding type is null or whitespace.</exception>
    public CustomTransport(string daprType, bool supportsInput, bool supportsOutput)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(daprType);
        DaprType = daprType;
        SupportsInput = supportsInput;
        SupportsOutput = supportsOutput;
    }
}

