4	namespace Intropy.Topology.Validation.Rules;
5	
6	/// <summary>ITP105: reading through a connector (<c>From</c>) requires a transport whose
7	/// Dapr binding type supports input. Unresolved connectors (no transport) are skipped —
8	/// their capabilities are unknown until resolved (see ITP107).</summary>
9	internal sealed class ConnectorInputCapabilityRule : ITopologyRule
10	{
11	    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
12	    {
13	        foreach (var component in context.Builder.Components)
14	        {
15	            var violations = InputUsages(component)
16	                .Distinct()
17	                .Where(c => c.Transport is { SupportsInput: false });
18	            foreach (var connector in violations)
19	            {
20	                yield return new TopologyDiagnostic(
21	                    "ITP105",
22	                    DiagnosticSeverity.Error,
23	                    $"The connector '{connector.Name}' is used for input, but its transport ('{connector.Transport!.DaprType}') does not support input.",
24	                    component.Name);
25	            }
26	        }
27	    }
28	
29	    private static IEnumerable<ConnectorRef> InputUsages(Component component)
30	    {
31	        foreach (var (connector, direction) in component.ConnectorCalls)
32	        {
33	            if (direction == ConnectorDirection.In)
34	            {
35	                yield return connector;
36	            }
37	        }
38	    }
39	}
40	
41	/// <summary>ITP106: writing through a connector (<c>To</c>) requires a transport whose
42	/// Dapr binding type supports output. Unresolved connectors (no transport) are skipped —
43	/// their capabilities are unknown until resolved (see ITP107).</summary>
44	internal sealed class ConnectorOutputCapabilityRule : ITopologyRule
45	{
46	    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
47	    {
48	        foreach (var component in context.Builder.Components)
49	        {
50	            var violations = component.ConnectorCalls
51	                .Where(c => c.Direction == ConnectorDirection.Out)
52	                .Select(c => c.Connector)
53	                .Distinct()
54	                .Where(c => c.Transport is { SupportsOutput: false });
55	            foreach (var connector in violations)
56	            {
57	                yield return new TopologyDiagnostic(
58	                    "ITP106",
59	                    DiagnosticSeverity.Error,
60	                    $"The connector '{connector.Name}' is used for output, but its transport ('{connector.Transport!.DaprType}') does not support output.",
61	                    component.Name);
62	            }
63	        }
64	    }
65	}
66	
67	/// <summary>
68	/// ITP107 (warning): a connector missing its external system or its transport is unresolved —
69	/// the block scaffold names the connector, but <em>what</em> it connects to and <em>how</em> are
70	/// bound at system assembly (<c>intropy system create</c>). Until then its Dapr binding type is
71	/// unset and its direction capabilities go unchecked (ITP105/ITP106). Warning severity so a
72	/// SystemHost still builds before the connector is resolved.
73	/// </summary>
74	internal sealed class UnresolvedConnectorRule : ITopologyRule
75	{
76	    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
77	    {
78	        foreach (var connector in context.Topology.Connectors)
79	        {
80	            var missing = new List<string>();
81	            if (connector.ExternalSystemName is null)
82	            {
83	                missing.Add("external system");
84	            }
85	
86	            if (connector.Transport is null)
87	            {
88	                missing.Add("transport");
89	            }
90	
91	            if (missing.Count == 0)
92	            {
93	                continue;
94	            }
95	
96	            yield return new TopologyDiagnostic(
97	                "ITP107",
98	                DiagnosticSeverity.Warning,
99	                $"The connector '{connector.Name}' is unresolved ({string.Join(" and ", missing)} not declared); " +
100	                "its Dapr binding type is unset and direction capabilities are unchecked. " +
101	                "Resolve it with 'intropy system create'.",
102	                connector.Name);
103	        }
104	    }
105	}
