50	/// <summary>Turns a validated <see cref="SystemTopology"/> into Dapr components and runtime config.</summary>
51	public static class TopologyGenerator
52	{
53	    private static readonly JsonSerializerOptions s_json = new() { WriteIndented = true };
54	
55	    /// <summary>Generates the artifacts for a topology under the given profile.</summary>
56	    /// <param name="topology">The validated topology.</param>
57	    /// <param name="profile">The target profile.</param>
58	    /// <param name="dev">Dev-only declarations (mocks/overrides); ignored for <see cref="GenerationProfile.Prod"/>.</param>
59	    /// <returns>The generated artifacts.</returns>
60	    public static GeneratedArtifacts Generate(SystemTopology topology, GenerationProfile profile, DevManifest? dev = null)
61	    {
62	        ArgumentNullException.ThrowIfNull(topology);
63	        var manifest = dev ?? DevManifest.Empty;
64	        var files = new List<GeneratedFile>();
65	
66	        foreach (var topic in topology.Topics.Select(t => t.PubSubName).Distinct(StringComparer.Ordinal))
67	        {
68	            files.Add(PubSubComponent(topic, profile, topology));
69	        }
70	
71	        foreach (var connector in topology.Connectors)
72	        {
73	            files.Add(BindingComponent(connector, profile, manifest));
74	        }
75	
76	        if (profile == GenerationProfile.Dev)
77	        {
78	            foreach (var api in topology.Apis)
79	            {
80	                if (manifest.ApiMockFor(api.Name) is { } apiMock && api.Providers.Count == 1)
81	                {
82	                    files.Add(HttpEndpointForMockedApi(api.Providers[0], apiMock));
83	                }
84	            }
85	        }
86	
87	        foreach (var component in topology.Components)
88	        {
89	            files.Add(ComponentConfig(topology.SystemName, component));
90	        }
91	
92	        return new GeneratedArtifacts(files);
93	    }
