110	    private static GeneratedFile BindingComponent(ConnectorResource connector, GenerationProfile profile, DevManifest manifest)
111	    {
112	        var metadata = new List<(string, string)>();
113	        // Dev metadata is keyed by external system; an unresolved connector has none to look up.
114	        if (profile == GenerationProfile.Dev && connector.ExternalSystemName is { } externalSystem)
115	        {
116	            var declared = manifest.ConnectorMetadataFor(externalSystem);
117	            if (declared.Count > 0)
118	            {
119	                // The dev profile declared how to reach the mock — emit it verbatim.
120	                metadata.AddRange(declared);
121	            }
122	            else if (connector.Transport?.DaprType == "bindings.http"
123	                && manifest.HttpApiMockFor(externalSystem) is { } httpMock)
124	            {
125	                metadata.Add(("url", httpMock.MockEndpoint));
126	            }
127	            else if (manifest.MockFor(externalSystem) is { Port: { } port })
128	            {
129	                // Dev placeholder endpoint — precise per-transport metadata is a downstream concern.
130	                metadata.Add(connector.Transport?.DaprType == "bindings.http"
131	                    ? ("url", $"http://localhost:{port}")
132	                    : ("endpoint", $"localhost:{port}"));
