182	internal static class DaprYaml
183	{
184	    public static string HttpEndpoint(string name, string baseUrl)
185	    {
186	        var sb = new StringBuilder();
187	        sb.Append("apiVersion: dapr.io/v1alpha1\n");
188	        sb.Append("kind: HTTPEndpoint\n");
189	        sb.Append("metadata:\n");
190	        sb.Append("  name: ").Append(Quote(name)).Append('\n');
191	        sb.Append("spec:\n");
192	        sb.Append("  baseUrl: ").Append(Quote(baseUrl)).Append('\n');
193	        return sb.ToString();
194	    }
195	
196	    public static string Component(
197	        string name,
198	        string type,
199	        IEnumerable<(string Key, string Value)> metadata,
200	        IEnumerable<string> scopes,
201	        string? leadingComment = null)
202	    {
203	        var meta = metadata.ToList();
204	        var scopeList = scopes.ToList();
205	
206	        var sb = new StringBuilder();
207	        if (leadingComment is not null)
208	        {
209	            sb.Append("# ").Append(leadingComment).Append('\n');
210	        }
211	
212	        sb.Append("apiVersion: dapr.io/v1alpha1\n");
213	        sb.Append("kind: Component\n");
214	        sb.Append("metadata:\n");
215	        sb.Append("  name: ").Append(Quote(name)).Append('\n');
216	        sb.Append("spec:\n");
217	        sb.Append("  type: ").Append(Quote(type)).Append('\n');
218	        sb.Append("  version: v1\n");
219	        if (meta.Count == 0)
220	        {
221	            sb.Append("  metadata: []\n");
222	        }
223	        else
224	        {
225	            sb.Append("  metadata:\n");
226	            foreach (var (key, value) in meta)
227	            {
228	                sb.Append("  - name: ").Append(Quote(key)).Append('\n');
229	                sb.Append("    value: ").Append(Quote(value)).Append('\n');
230	            }
231	        }
232	
233	        if (scopeList.Count > 0)
234	        {
235	            sb.Append("scopes:\n");
236	            foreach (var scope in scopeList)
237	            {
238	                sb.Append("- ").Append(Quote(scope)).Append('\n');
239	            }
240	        }
241	
242	        return sb.ToString();
243	    }
244	
245	    private static string Quote(string value) =>
246	        $"\"{value.Replace("\\", "\\\\", StringComparison.Ordinal).Replace("\"", "\\\"", StringComparison.Ordinal)}\"";
247	}
