using System.Reflection;
using Aspire.Hosting;
using Aspire.Hosting.ApplicationModel;
using CommunityToolkit.Aspire.Hosting.Dapr;
using Intropy.Topology.Generation;
using Intropy.Topology.Model;
using Microsoft.Extensions.DependencyInjection;

namespace Intropy.Topology.Aspire;

/// <summary>
/// The Aspire run-backend. Discovers a system's validated topology, generates dev Dapr components,
/// and translates the model into Aspire resources — one project (or dev-override container) per
/// component with a Dapr sidecar on its own staged component overlay, Redis behind pub/sub, mock
/// containers for declared external systems, and one Microcks instance serving every
/// contract-backed mock — then runs it under DCP, subscribers before their publishers.
/// Aspire never sees the topology; it receives ordinary resources.
/// </summary>
public static class IntropyAspire
{
    /// <summary>Fixed host port for the dev Redis backend (generated pub/sub YAML points here).</summary>
    internal const int RedisPort = 6379;

    /// <summary>
    /// Discovers the system in <paramref name="assembly"/>, generates dev artifacts to a temp folder,
    /// builds the Aspire resource graph, and runs it. Requires Docker and the Dapr CLI to be present.
    /// </summary>
    /// <param name="assembly">The assembly declaring the <see cref="ISystemDefinition"/>.</param>
    /// <param name="args">Command-line args passed through to the distributed application builder.</param>
    /// <returns>A process exit code.</returns>
    public static async Task<int> RunAsync(Assembly assembly, string[] args)
    {
        ArgumentNullException.ThrowIfNull(assembly);
        ArgumentNullException.ThrowIfNull(args);

        var discovered = SystemDiscovery.Discover(assembly);
        var dev = DevManifest.From(discovered.Definition);

        var generatedRoot = Path.Combine(
            Path.GetTempPath(), "intropy-aspire", $"{discovered.Topology.SystemName}-{Guid.NewGuid():N}");
        TopologyGenerator.Generate(discovered.Topology, GenerationProfile.Dev, dev).WriteTo(generatedRoot);

        var builder = DistributedApplication.CreateBuilder(args);
        Apply(builder, discovered.Topology, dev, generatedRoot);

        var app = builder.Build();
        await app.RunAsync().ConfigureAwait(false);
        return 0;
    }

    /// <summary>
    /// Translates the topology into Aspire resources on <paramref name="builder"/>. Separated from
    /// <see cref="RunAsync"/> so the built model can be inspected in tests without running DCP.
    /// </summary>
    internal static void Apply(
        IDistributedApplicationBuilder builder, SystemTopology topology, DevManifest dev, string generatedRoot)
    {
        // A connector with no transport has no Dapr binding type to run against — you cannot F5 an
        // unresolved binding. Fail fast (no run/deploy-time prompting): the transport is resolved at
        // system assembly, not here.
        var unresolvedConnectors = topology.Connectors
            .Where(c => c.Transport is null)
            .Select(c => c.Name)
            .ToArray();
        if (unresolvedConnectors.Length > 0)
        {
            throw new InvalidOperationException(
                $"These connectors have no transport declared (unresolved): {string.Join(", ", unresolvedConnectors)}. " +
                "Resolve them with 'intropy system create' before running.");
        }

        var componentsPath = Path.Combine(generatedRoot, GeneratedArtifacts.ComponentsDir);
        var configDir = Path.Combine(generatedRoot, GeneratedArtifacts.ConfigDir);

        // A plain Redis container rather than AddRedis: the generated pub/sub YAML speaks
        // password-less plaintext to localhost:6379, while AddRedis fronts Redis with TLS.
        var redis = builder
            .AddContainer("redis", "docker.io/library/redis", "8")
            .WithEndpoint(port: RedisPort, targetPort: RedisPort);
        WithTcpReadiness(builder, redis, RedisPort);

        // Everything a sidecar dials during component init. Sidecars must wait for these to be
        // *ready* (not merely running) — daprd treats a failed component init as fatal, so racing
        // a still-starting mock kills the sidecar.
        var backends = new List<IResourceBuilder<IResource>> { redis };
        var backendProbes = new List<TcpReadyHealthCheck> { new("localhost", RedisPort) };

        foreach (var mock in dev.Mocks)
        {
            var container = builder.AddContainer($"mock-{mock.ExternalSystemName}", mock.Image);
            if (mock.Args.Count > 0)
            {
                container.WithArgs([.. mock.Args]);
            }

            if (mock.Port is { } port)
            {
                container.WithEndpoint(port: port, targetPort: mock.TargetPort ?? port);
                WithTcpReadiness(builder, container, port);
                backendProbes.Add(new("localhost", port));
            }

            backends.Add(container);
        }

        var mockedProviders = MockedApiProviders(topology, dev);
        var microcksArtifacts = dev.HttpApiMocks.Select(m => m.ArtifactPath)
            .Concat(dev.ApiMocks.Select(m => m.ArtifactPath))
            .ToArray();
        if (microcksArtifacts.Length > 0)
        {
            // One Microcks instance serves every contract-backed mock. The generated YAML points at
            // the fixed dev port, so pin the host port ("http" is the resource's primary endpoint).
            var microcks = builder.AddMicrocks("microcks")
                .WithEndpoint("http", e => e.Port = DevHttpMock.Port)
                .WithMainArtifacts(microcksArtifacts);
            backends.Add(microcks);
            backendProbes.Add(new("localhost", DevHttpMock.Port));
        }

