// An extractor reading the system-assembly default: a file connector rooted in the host's test folder.
private static SystemTopology FileConnectorTopology()
{
    var s = SystemBuilder.Create("order-fulfillment");
    s.AddExtractor("order-extractor")
        .From(ConnectorRef.Define("order-extractor-source", Transport.File("./test/order-extractor-source")))
        .Publishes(OrderSystem.Raw);
    s.AddLoader("erp-order-loader").Subscribes(OrderSystem.Raw);
