1	namespace Intropy.Topology.Aspire;
2	
3	/// <summary>
4	/// Stages the effective Dapr component set for one integration: everything from its own
5	/// <c>local/dapr-components/</c> passes through, then the system's generated components overlay
6	/// it — a generated component with the same <c>metadata.name</c> replaces the local one, new
7	/// names are added. The staged set lands at a stable, inspectable path under the AppHost's
8	/// <c>obj/dapr-components/&lt;component&gt;/</c> and is regenerated on every start; the
9	/// integration's sidecar gets it as its resources path. Standalone runs load the local
10	/// directory instead — same names, different backing.
11	/// </summary>
12	internal static class ComponentOverlay
13	{
14	    /// <summary>Stages the component set and returns the staged directory.</summary>
15	    public static string Stage(string appHostDirectory, string componentName, string generatedComponentsDir)
16	    {
17	        var stagedDir = Path.Combine(appHostDirectory, "obj", "dapr-components", componentName);
18	        if (Directory.Exists(stagedDir))
19	        {
20	            Directory.Delete(stagedDir, recursive: true);
21	        }
22	
23	        Directory.CreateDirectory(stagedDir);
24	
25	        // metadata.name -> staged file, so a generated component can replace its local counterpart.
26	        var stagedByName = new Dictionary<string, string>(StringComparer.Ordinal);
27	        foreach (var file in ComponentFiles(ProjectConvention.LocalComponentsDir(appHostDirectory, componentName)))
28	        {
29	            var target = Path.Combine(stagedDir, Path.GetFileName(file));
30	            File.Copy(file, target);
31	            if (MetadataName(File.ReadAllText(file)) is { } name)
32	            {
33	                stagedByName[name] = target;
34	            }
35	        }
36	
37	        foreach (var file in ComponentFiles(generatedComponentsDir))
38	        {
39	            var name = MetadataName(File.ReadAllText(file));
40	            if (name is not null && stagedByName.TryGetValue(name, out var replaced))
41	            {
42	                File.Delete(replaced);
43	            }
44	
45	            var target = Path.Combine(stagedDir, Path.GetFileName(file));
46	            File.Copy(file, target, overwrite: true);
47	            if (name is not null)
48	            {
49	                stagedByName[name] = target;
50	            }
51	        }
52	
53	        return stagedDir;
54	    }
55	
56	    /// <summary>
57	    /// The top-level <c>metadata.name</c> of a Dapr resource YAML. Only the unindented
58	    /// <c>metadata:</c> block qualifies — <c>spec.metadata</c> entries are indented past it.
59	    /// </summary>
60	    internal static string? MetadataName(string yaml)
61	    {
62	        var lines = yaml.Split('\n');
63	        for (var i = 0; i < lines.Length; i++)
64	        {
65	            if (lines[i].TrimEnd() != "metadata:")
66	            {
67	                continue;
68	            }
69	
70	            for (var j = i + 1; j < lines.Length && lines[j].StartsWith(' '); j++)
71	            {
72	                var entry = lines[j].Trim();
73	                if (entry.StartsWith("name:", StringComparison.Ordinal))
74	                {
75	                    return entry["name:".Length..].Trim().Trim('"', '\'');
76	                }
77	            }
78	        }
79	
80	        return null;
81	    }
82	
83	    private static IEnumerable<string> ComponentFiles(string directory) =>
84	        Directory.Exists(directory)
85	            ? Directory.EnumerateFiles(directory)
86	                .Where(f => f.EndsWith(".yaml", StringComparison.OrdinalIgnoreCase)
87	                    || f.EndsWith(".yml", StringComparison.OrdinalIgnoreCase))
88	                .OrderBy(f => f, StringComparer.Ordinal)
89	            : [];
90	}
