31		for _, e := range entries {
32			switch {
33			case e.Role == template.RoleSharedLibrary:
34				name, err := stringValue(e, "name")
35				if err != nil {
36					return nil, err
37				}
38				shared = append(shared, SharedLibrary{Path: e.Path, Name: name})
39				continue
40			case e.Role == template.RoleSystemHost:
41				warnf("skipping %s: an existing system host", e.Path)
42				continue
43			case e.BlockKind == "":
44				warnf("skipping %s: scaffold record has no block kind — re-scaffold with a newer template release to include it", e.Path)
45				continue
46			case e.BlockKind != template.BlockKindExtractor && e.BlockKind != template.BlockKindLoader:
47				warnf("skipping %s: unsupported block kind %q (sys create assembles extractors and loaders only)", e.Path, e.BlockKind)
48				continue
49			}
50	
51			appID, err := stringValue(e, "appId")
52			if err != nil {
53				return nil, err
54			}
55			topic, err := stringValue(e, "topic")
56			if err != nil {
57				return nil, err
58			}
59			contract, err := stringValue(e, "contract")
60			if err != nil {
61				return nil, fmt.Errorf("%w\nRe-scaffold this integration with a template release that records the contract type, or add \"contract\": \"<TypeName>\" to the record's values.", err)
62			}
63			pubsub, err := stringValueDefault(e, "pubsub", "pubsub")
64			if err != nil {
65				return nil, err
66			}
67	
68			if prev, ok := byAppID[appID]; ok {
69				return nil, fmt.Errorf("duplicate component name %q: declared by both %s and %s (component names must be unique in a system)", appID, prev, e.Path)
70			}
71			byAppID[appID] = e.Path
72	
73			key := TopicKey{Pubsub: pubsub, Name: topic}
74			if seen, ok := byTopic[key]; ok {
75				if seen.Contract != contract {
76					return nil, fmt.Errorf("topic %q on pubsub %q has conflicting contracts: %q (%s) vs %q (%s)", topic, pubsub, seen.Contract, firstDir[key], contract, e.Path)
77				}
78			} else {
79				byTopic[key] = Topic{TopicKey: key, Contract: contract, Field: pascalIdent(topic)}
80				firstDir[key] = e.Path
81			}
82	
83			components = append(components, Component{AppID: appID, Kind: e.BlockKind, Topic: key, Path: e.Path})
84		}
85	
86		if len(components) == 0 {
87			return nil, fmt.Errorf("%w in this directory\nScaffold extractors and loaders first ('intropy int create extractor -n <Name> -s topic=<topic> ...'), then run 'intropy sys create' from the workspace root.", ErrNoComponents)
88		}
89		switch {
90		case len(shared) == 0:
91			return nil, fmt.Errorf("no shared contracts project found (template role %q): Topics.cs needs the contract types\nComponents scaffolded from the official extractor/loader templates create a sibling Contracts/ project automatically.", template.RoleSharedLibrary)
92		case len(shared) > 1:
93			dirs := make([]string, len(shared))
94			for i, s := range shared {
95				dirs[i] = s.Path
96			}
97			return nil, fmt.Errorf("found %d shared contract projects (%s); a system host references exactly one — remove or consolidate before re-running", len(shared), strings.Join(dirs, ", "))
98		}
99	
100		topics := make([]Topic, 0, len(byTopic))
101		for _, t := range byTopic {
102			topics = append(topics, t)
103		}
104		sort.Slice(topics, func(i, j int) bool {
105			if topics[i].Pubsub != topics[j].Pubsub {
106				return topics[i].Pubsub < topics[j].Pubsub
107			}
108			return topics[i].Name < topics[j].Name
109		})
110	
111		fields := map[string]TopicKey{}
112		for _, t := range topics {
113			if prev, ok := fields[t.Field]; ok {
114				return nil, fmt.Errorf("topics %q (pubsub %q) and %q (pubsub %q) both map to field %s in Topics.cs; rename one topic", prev.Name, prev.Pubsub, t.Name, t.Pubsub, t.Field)
115			}
116			fields[t.Field] = t.TopicKey
117		}
118	
119		return &Model{Components: components, Topics: topics, Shared: shared[0]}, nil
120	}
