122	// stringValue returns values[key] as a non-empty string, with errors that
123	// name the record so the user knows which project to fix.
124	func stringValue(e template.ScaffoldEntry, key string) (string, error) {
125		record := filepath.Join(e.Path, filepath.FromSlash(template.ScaffoldRelPath))
126		v, ok := e.Values[key]
127		if !ok {
128			return "", fmt.Errorf("%s: values.%s is missing", record, key)
129		}
130		s, ok := v.(string)
131		if !ok {
132			return "", fmt.Errorf("%s: values.%s has type %T, expected string", record, key, v)
133		}
134		if s == "" {
135			return "", fmt.Errorf("%s: values.%s is empty", record, key)
136		}
137		return s, nil
138	}
139	
140	// stringValueDefault is stringValue with a fallback for records that
141	// predate the value being recorded.
142	func stringValueDefault(e template.ScaffoldEntry, key, fallback string) (string, error) {
143		if _, ok := e.Values[key]; !ok {
144			return fallback, nil
145		}
146		return stringValue(e, key)
147	}
148	
149	// pascalIdent converts a DNS-ish name to a C# identifier: segments split
150	// on '-', '.' and '_' are title-cased and joined ("order-events" →
151	// "OrderEvents").
152	func pascalIdent(s string) string {
153		segments := strings.FieldsFunc(s, func(r rune) bool {
154			return r == '-' || r == '.' || r == '_'
155		})
156		var b strings.Builder
157		for _, seg := range segments {
158			b.WriteString(strings.ToUpper(seg[:1]))
159			b.WriteString(seg[1:])
160		}
161		return b.String()
162	}
