1	// Package system assembles scaffolded integrations into a system host. It
2	// scans the workspace for the .intropy/scaffold.json records `int create`
3	// left behind, renders the system-host template with the template
4	// package's machinery, and generates the typed system declaration —
5	// Topics.cs and the ISystemDefinition class — from what the scaffolds
6	// recorded.
7	package system
8	
9	import (
10		"context"
11		"encoding/json"
12		"fmt"
13		"io"
14		"net/http"
15		"os"
16		"path/filepath"
17		"strings"
18	
19		"github.com/huandu/xstrings"
20	
21		"github.com/integrio-intropy/intropy-cli/internal/template"
22	)
23	
24	// hostTemplate is the directory in the templates repo holding the system
25	// host's shell and placeholders.
26	const hostTemplate = "system-host"
27	
28	type CreateOptions struct {
29		Name       string // system name as typed; PascalCase or kebab-case
30		StartDir   string // workspace scan root; default "."
31		OutputDir  string // default: the kebab-cased name
32		Version    string // template release tag; default: latest
33		Force      bool
34		OutputJSON string // path to write CreateResult JSON; "-" means stdout
35		Stdout     io.Writer
36		Stderr     io.Writer
37		HTTP       *http.Client
38		UserAgent  string
39	
40		// Test overrides. Production callers leave these zero-valued; the CLI
41		// always targets the official template library.
42		Owner         string
43		Repo          string
44		GitHubBaseURL string
45	}
46	
47	// CreateResult is the machine-readable summary written when --output-json
48	// is set. Field names are stable and additive-only.
49	type CreateResult struct {
50		Template  string         `json:"template"`
51		Owner     string         `json:"owner"`
52		Repo      string         `json:"repo"`
53		Version   string         `json:"version"`
54		OutputDir string         `json:"outputDir"`
55		Values    map[string]any `json:"values"`
56		System    Summary        `json:"system"`
57	}
58	
59	// Summary describes the assembled system; it loosely mirrors the model the
60	// host's `graph` verb prints.
61	type Summary struct {
62		Name          string      `json:"name"`
63		Components    []Component `json:"components"`
64		Topics        []Topic     `json:"topics"`
65		SharedLibrary string      `json:"sharedLibrary"` // scaffold directory
66	}
67	
68	func (o *CreateOptions) applyDefaults() {
69		if o.StartDir == "" {
70			o.StartDir = "."
71		}
72		if o.Stdout == nil {
73			o.Stdout = os.Stdout
74		}
75		if o.Stderr == nil {
76			o.Stderr = os.Stderr
77		}
78		if o.UserAgent == "" {
79			o.UserAgent = "intropy-cli"
80		}
81	}
82	
83	// Create runs the full assembly: scan the workspace for scaffold records,
84	// validate them into a system model, render the system-host template, and
85	// generate the declaration files from the model. All local validation
86	// happens before any network I/O.
87	func Create(ctx context.Context, opts CreateOptions) error {
88		opts.applyDefaults()
89		if opts.Name == "" {
90			return fmt.Errorf("a system name is required")
91		}
92	
93		// Exact parity with the templates' `{{ .name | kebabcase }}`: sprig
94		// delegates to xstrings, so OrderFlow and order-flow are equivalent.
95		kebab := xstrings.ToKebabCase(opts.Name)
96		if opts.OutputDir == "" {
97			opts.OutputDir = kebab
98		}
99	
100		entries, warnings := template.ListScaffolds(opts.StartDir)
101		for _, w := range warnings {
102			fmt.Fprintf(opts.Stderr, "warning: %v\n", w)
103		}
104		model, err := Assemble(entries, func(format string, args ...any) {
105			fmt.Fprintf(opts.Stderr, "warning: "+format+"\n", args...)
106		})
107		if err != nil {
108			return err
109		}
110		model.Name = kebab
111	
112		include, err := contractsInclude(opts.OutputDir, model.Shared)
113		if err != nil {
114			return err
115		}
116	
117		if err := template.Create(ctx, template.CreateOptions{
118			Template:      hostTemplate,
119			OutputDir:     opts.OutputDir,
120			Version:       opts.Version,
121			SetValues:     map[string]any{"name": kebab},
122			Force:         opts.Force,
123			NoInput:       true, // the template's contract: only `name`, never prompt
124			Stdin:         strings.NewReader(""),
125			Stdout:        opts.Stdout,
126			Stderr:        opts.Stderr,
127			HTTP:          opts.HTTP,
128			UserAgent:     opts.UserAgent,
129			Owner:         opts.Owner,
130			Repo:          opts.Repo,
131			GitHubBaseURL: opts.GitHubBaseURL,
132		}); err != nil {
133			return err
134		}
135	
136		// The template derives projectName/systemClass from the name; reading
137		// them back from the record it just wrote makes CLI/template
138		// derivation drift impossible.
139		record, err := template.LoadScaffold(filepath.Join(opts.OutputDir, filepath.FromSlash(template.ScaffoldRelPath)))
140		if err != nil {
141			return err
142		}
143		hostEntry := template.ScaffoldEntry{Path: opts.OutputDir, Scaffold: *record}
144		if model.ProjectName, err = stringValue(hostEntry, "projectName"); err != nil {
145			return fmt.Errorf("template %s did not derive the host project name: %w", hostTemplate, err)
146		}
147		if model.SystemClass, err = stringValue(hostEntry, "systemClass"); err != nil {
148			return fmt.Errorf("template %s did not derive the system class name: %w", hostTemplate, err)
149		}
150	
151		if err := writeTopicsFile(opts.OutputDir, model); err != nil {
152			return err
153		}
154		if err := writeSystemClassFile(opts.OutputDir, model); err != nil {
155			return err
156		}
157		csproj := filepath.Join(opts.OutputDir, model.ProjectName+".SystemHost.csproj")
158		if err := insertProjectReference(csproj, include); err != nil {
159			return err
160		}
161	
162		fmt.Fprintf(opts.Stderr, "assembled system %q: %d component(s), %d topic(s), contracts from %s\n",
163			model.Name, len(model.Components), len(model.Topics), model.Shared.Path)
164	
165		return maybeWriteCreateResult(opts, record, model)
166	}
167	
168	func maybeWriteCreateResult(opts CreateOptions, record *template.Scaffold, model *Model) error {
169		if opts.OutputJSON == "" {
170			return nil
171		}
172		absOut, err := filepath.Abs(opts.OutputDir)
173		if err != nil {
174			absOut = opts.OutputDir
175		}
176		result := CreateResult{
177			Template:  hostTemplate,
178			Owner:     record.Owner,
179			Repo:      record.Repo,
180			Version:   record.Version,
181			OutputDir: absOut,
182			Values:    record.Values,
183			System: Summary{
184				Name:          model.Name,
185				Components:    model.Components,
186				Topics:        model.Topics,
187				SharedLibrary: model.Shared.Path,
188			},
189		}
190		data, err := json.MarshalIndent(result, "", "  ")
191		if err != nil {
192			return fmt.Errorf("write --output-json: %w", err)
193		}
194		data = append(data, '\n')
195		if opts.OutputJSON == "-" {
196			if _, err := opts.Stdout.Write(data); err != nil {
197				return fmt.Errorf("write --output-json: %w", err)
198			}
199			return nil
200		}
201		if err := os.WriteFile(opts.OutputJSON, data, 0o644); err != nil {
202			return fmt.Errorf("write --output-json: %w", err)
203		}
204		return nil
205	}
