package system

// Temporary end-to-end harness: renders the REAL templates from the local
// intropy-templates checkout (served as a fake GitHub release) and runs the
// tutorial flow — int create extractor + loader, then sys create. Skipped
// unless the checkout exists. NOT meant to be committed: delete after manual
// verification.

import (
	"archive/tar"
	"bytes"
	"compress/gzip"
	"context"
	"io/fs"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

const localTemplatesDir = "/Users/robinhultman/dev/intropy/tooling/intropy-templates"

func buildLocalTemplatesTarball(t *testing.T) []byte {
	t.Helper()
	var buf bytes.Buffer
	gz := gzip.NewWriter(&buf)
	tw := tar.NewWriter(gz)
	err := filepath.WalkDir(localTemplatesDir, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			if d.Name() == ".git" {
				return filepath.SkipDir
			}
			return nil
		}
		rel, err := filepath.Rel(localTemplatesDir, path)
		if err != nil {
			return err
		}
		data, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		h := &tar.Header{Name: "owner-repo-local/" + filepath.ToSlash(rel), Mode: 0o644, Size: int64(len(data)), Typeflag: tar.TypeReg}
		if err := tw.WriteHeader(h); err != nil {
			return err
		}
		_, err = tw.Write(data)
		return err
	})
	if err != nil {
		t.Fatal(err)
	}
	if err := tw.Close(); err != nil {
		t.Fatal(err)
	}
	if err := gz.Close(); err != nil {
		t.Fatal(err)
	}
	return buf.Bytes()
}

func TestE2ELocalTemplatesTutorialFlow(t *testing.T) {
	if _, err := os.Stat(localTemplatesDir); err != nil {
		t.Skip("local intropy-templates checkout not present")
	}
	tarball := buildLocalTemplatesTarball(t)
	mux := http.NewServeMux()
	mux.HandleFunc("/repos/o/r/releases/latest", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"tag_name":"vlocal"}`))
	})
	mux.HandleFunc("/repos/o/r/tarball/vlocal", func(w http.ResponseWriter, r *http.Request) {
		_, _ = w.Write(tarball)
	})
	srv := httptest.NewServer(mux)
	defer srv.Close()

	ws := t.TempDir()
	var stderr bytes.Buffer
	intCreate := func(tmpl, name string) {
		t.Helper()
		err := template.Create(context.Background(), template.CreateOptions{
			Template:  tmpl,
			OutputDir: filepath.Join(ws, name),
			Version:   "vlocal",
			SetValues: map[string]any{
				"name": name, "organization": "Fluxia", "topic": "orders", "contract": "Order",
			},
			NoInput:       true,
			Stdin:         strings.NewReader(""),
			Stdout:        &stderr,
			Stderr:        &stderr,
			HTTP:          srv.Client(),
			UserAgent:     "test",
			Owner:         "o",
			Repo:          "r",
			GitHubBaseURL: srv.URL,
		})
		if err != nil {
			t.Fatalf("int create %s: %v\nstderr: %s", tmpl, err, stderr.String())
		}
	}
	intCreate("extractor", "OrderExtractor")
	intCreate("loader", "OrderLoader")

	// The extractor's record must carry the derived connector.
	record, err := template.LoadScaffold(filepath.Join(ws, "OrderExtractor", filepath.FromSlash(template.ScaffoldRelPath)))
	if err != nil {
		t.Fatal(err)
	}
	if record.Values["connector"] != "order-extractor-source" {
		t.Errorf("extractor connector = %v", record.Values["connector"])
	}

	// The rendered Dapr component and Constants must share the binding name.
	inbound, err := os.ReadFile(filepath.Join(ws, "OrderExtractor", "local", "dapr-components", "inbound.yaml"))
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(inbound), "name: binding.order-extractor-source") ||
		!strings.Contains(string(inbound), `value: "./local/storage/order-extractor-source"`) {
		t.Errorf("inbound.yaml:\n%s", inbound)
	}
	constants, err := os.ReadFile(filepath.Join(ws, "OrderExtractor", "src", "Configuration", "Constants.cs"))
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(constants), `InboundBindingName = "binding.order-extractor-source"`) {
		t.Errorf("Constants.cs:\n%s", constants)
	}

	// sys create over the rendered workspace.
	outDir := filepath.Join(ws, "system-host")
	var sysStderr bytes.Buffer
	err = Create(context.Background(), CreateOptions{
		Name:          "OrderFlow",
		StartDir:      ws,
		OutputDir:     outDir,
		Version:       "vlocal",
		Stdout:        &sysStderr,
		Stderr:        &sysStderr,
